{
  "openapi": "3.1.0",
  "info": {
    "title": "Modulr API",
    "description": "Modulr API",
    "license": {
      "name": "© Modulr Finance",
      "url": "https://www.modulrfinance.com"
    },
    "version": "1.0"
  },
  "servers": [
    {
      "url": "https://api-sandbox.modulrfinance.com/api-sandbox-token"
    }
  ],
  "security": [
    {
      "modulo_security": []
    }
  ],
  "tags": [
    {
      "name": "File Upload",
      "description": "Upload payment files"
    }
  ],
  "paths": {
    "/payment-files/{fileId}/proceed": {
      "post": {
        "tags": [
          "File Upload"
        ],
        "summary": "Create payments from an uploaded file",
        "description": "Create a batch payment request from a valid upload file and send for processing to the payment service",
        "operationId": "proceed",
        "parameters": [
          {
            "name": "fileId",
            "in": "path",
            "description": "Payment File ID",
            "required": true,
            "style": "simple",
            "explode": false,
            "schema": {
              "type": "string"
            }
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/paymentfileupload.FileCreateRequest"
              }
            }
          },
          "required": true
        },
        "responses": {
          "201": {
            "description": "File created response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/paymentfileupload.FileCreatePaymentsResponse"
                }
              }
            }
          },
          "400": {
            "description": "Invalid payment file",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/paymentfileupload.MessageResponse"
                  }
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "paymentfileupload.FileCreatePaymentsResponse": {
        "type": "object",
        "description": "File create payments response",
        "properties": {
          "fileId": {
            "type": "string",
            "description": "Unique id of the uploaded file",
            "example": "F1100001",
            "minLength": 1
          },
          "status": {
            "type": "string",
            "description": "Status of the uploaded file",
            "enum": [
              "NEW",
              "SUBMITTED",
              "PROCESSING",
              "INVALID",
              "VALID",
              "DUPLICATE",
              "REJECTED",
              "ERROR_RETRYABLE",
              "ACCEPTED",
              "PROCESSED",
              "SENDING",
              "PAYMENT_PROCESSING",
              "SPLIT_FILE",
              "PARTIALLY_ACCEPTED"
            ],
            "example": "INVALID"
          },
          "fileName": {
            "type": "string",
            "description": "File name of the uploaded file",
            "example": "file1"
          },
          "batchPaymentId": {
            "type": "string",
            "description": "Unique id for the Batch Payment",
            "example": "B1100001",
            "minLength": 1
          }
        },
        "required": [
          "batchPaymentId",
          "fileId",
          "status"
        ]
      },
      "paymentfileupload.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
              "MFADEVICEMM",
              "MFAMESSAGEINVALID",
              "NOTFOUND",
              "DUPLICATE",
              "INVALID",
              "CONNECTION",
              "RETRY",
              "RATELIMIT",
              "PERMISSION",
              "NOTACCEPTABLE",
              "MFAVERIFICATION",
              "TOKENEXPIRED"
            ]
          },
          "errorCode": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "sourceService": {
            "type": "string"
          }
        }
      },
      "paymentfileupload.FileCreateRequest": {
        "type": "object",
        "description": "File create payments request body",
        "properties": {
          "useDuplicate": {
            "type": "boolean",
            "description": "User confirms to proceed with creating payments on a duplicate file"
          }
        }
      }
    },
    "securitySchemes": {
      "modulo_security": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      },
      "TOKEN": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      }
    }
  },
  "x-readme": {
    "proxy-enabled": false
  }
}
